using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly EvaluationResponse _evaluationMetrics;
    private readonly string[] _classLabels;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Text
                .FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(dataView);
        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract ordered class labels from the trained model's key-value mapping
        var transformedData = _model.Transform(dataView);
        var labelColumn = transformedData.Schema["Label"];
        var keyType = labelColumn.Type as Microsoft.ML.Data.KeyDataViewType;
        VBuffer<ReadOnlyMemory<char>> keyValues = default;
        labelColumn.GetKeyValues(ref keyValues);
        _classLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();

        _evaluationMetrics = Evaluate(dataView);
    }

    private EvaluationResponse Evaluate(IDataView dataView)
    {
        var predictions = _model.Transform(dataView);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        var perClass = new List<PerClassMetric>();
        for (int i = 0; i < _classLabels.Length; i++)
        {
            perClass.Add(new PerClassMetric
            {
                Class = _classLabels[i],
                Precision = i < metrics.PerClassPrecision.Count ? metrics.PerClassPrecision[i] : 0,
                Recall = i < metrics.PerClassRecall.Count ? metrics.PerClassRecall[i] : 0,
                F1Score = i < metrics.PerClassPrecision.Count && i < metrics.PerClassRecall.Count
                    ? 2 * metrics.PerClassPrecision[i] * metrics.PerClassRecall[i]
                      / (metrics.PerClassPrecision[i] + metrics.PerClassRecall[i])
                    : 0
            });
        }

        return new EvaluationResponse
        {
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction,
            PerClassMetrics = perClass.ToArray()
        };
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var prediction = _predictionEngine.Predict(new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        });

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _classLabels.Length; i++)
        {
            confidence[_classLabels[i]] = prediction.Score[i];
        }

        return new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public EvaluationResponse GetMetrics() => _evaluationMetrics;
}

